// Immediate local cue; response speech is generated by the Linux server.
export const preferenceKey='delta-voice';
export function cancelSpeech(){if(typeof speechSynthesis!=='undefined')speechSynthesis.cancel();}
let feedback:AudioContext|undefined;
export function prepareFeedback(){
  try{feedback??=new AudioContext();void feedback.resume().catch(()=>{});}catch{/* Visual feedback remains available. */}
}
export function acknowledge(){
  // Called before dispatch, without waiting for speech to finish.
  if(feedback?.state==='running'){
    const oscillator=feedback.createOscillator(),gain=feedback.createGain();
    oscillator.connect(gain);gain.connect(feedback.destination);
    oscillator.frequency.setValueAtTime(540,feedback.currentTime);
    oscillator.frequency.exponentialRampToValueAtTime(760,feedback.currentTime+.12);
    gain.gain.setValueAtTime(.0001,feedback.currentTime);
    gain.gain.exponentialRampToValueAtTime(.06,feedback.currentTime+.02);
    gain.gain.exponentialRampToValueAtTime(.0001,feedback.currentTime+.18);
    oscillator.start();oscillator.stop(feedback.currentTime+.2);
    oscillator.onended=()=>{oscillator.disconnect();gain.disconnect();};
  }
}
export function releaseFeedback(){cancelSpeech();const current=feedback;feedback=undefined;if(current)void current.close().catch(()=>{});}

export function speechText(text:string){
  return text.replace(/```[\s\S]*?(?:```|$)/g,' Код приведён в тексте. ').replace(/!?\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/https?:\/\/\S+/g,'').replace(/<[^>]*>/g,'').replace(/[*_`#~|>]/g,'').replace(/\s+/g,' ').trim();
}
